import { ActionDefinition } from '../../../Action'
import { StringColumn, ReferenceColumn } from '../../../../db'

export const sendSms = ActionDefinition({
    $id: '027499be7333001099792f163cf6a7a7',
    name: 'Send SMS',
    description:
        'Send SMS to user records and group records using email-based SMS. If user records do not have an SMS device configured, an SMS will not be sent to that user.',
    inputs: {
        recipients: StringColumn({
            label: 'Recipients',
            mandatory: true,
            maxLength: 8000,
        }),
        message: StringColumn({
            label: 'Message',
            mandatory: true,
            maxLength: 8000,
        }),
    },
    outputs: {
        email: ReferenceColumn({
            label: 'Email',
            referenceTable: 'sys_email',
        }),
    },
})
